solution_code:
def validate_order(order: dict, errors: list | None = None) -> list[str]:
    if errors is None:
        errors = []
    if not order.get("order_id"):
        errors.append("missing order_id")
    qty = order.get("qty")
    if not isinstance(qty, int) or qty <= 0:
        errors.append("qty must be a positive integer")
    return errors
